-- The Bicol crop catalogue (src/lib/cropCatalogue.json): every vegetable, root
-- crop and fruit with 2025 production in Bicol (PSA OpenSTAT), plus food crops
-- from the non-food group and palay and corn. Growing times may be unknown.
ALTER TABLE "CropType" ALTER COLUMN "daysToHarvestMin" DROP NOT NULL;
ALTER TABLE "CropType" ALTER COLUMN "daysToHarvestMax" DROP NOT NULL;
ALTER TABLE "CropType" ADD COLUMN "category" TEXT NOT NULL DEFAULT 'Other vegetables';
ALTER TABLE "CropType" ADD COLUMN "aliases" TEXT[] DEFAULT ARRAY[]::TEXT[];
ALTER TABLE "CropType" ADD COLUMN "psaProductionTable" TEXT;
ALTER TABLE "CropType" ADD COLUMN "psaProduction" TEXT;
ALTER TABLE "CropType" ADD COLUMN "psaPriceTable" TEXT;
ALTER TABLE "CropType" ADD COLUMN "psaPrice" TEXT;

-- A listing that is not a farm crop (processed goods, fish...), so it
-- leaves the "not linked to a crop" list.
ALTER TABLE "Product" ADD COLUMN "notACrop" BOOLEAN NOT NULL DEFAULT false;

-- Add missing crops; for crops already there, fill in category, local names
-- and PSA series but keep the growing time and source staff may have set.

-- The catch-all crop stays, under its own category.
UPDATE "CropType" SET "category" = 'Other vegetables' WHERE "name" = 'Other vegetable';
